GimCorpus.put(411,0,[[1,13,"וכן אם אכל וכו'. כתב הראב\"ד ז\"ל זה אינו כלום שהרי אמרו והוא שלא טעם כלום כל אותו היום ועוד אמרו כל תענית שלא שקעה עליו חמה לא שמיה תענית. המימרא הראשונה מיעטה שאם אכל בחצי היום ורצה להתענות עד הערב לאו כלום היא כי מאחר שאכל שוב אינו מתענה. והמימרא השניה באה למעט מי שאמר אפילו בערב הריני בתענית עד חצי היום כי מאחר שלא יצא עליו היום בעינוי קבלתו לאו כלום היא, עכ\"ל:",1,0],[1,14,"שכח ואכל וכו'. א\"א ירושלמי בשאמר יום זה אבל אם אמר יום סתם אבד תעניתו, עכ\"ל:",1,0],[1,15,"על צרה ועברה וכו'. א\"א סובר זה המחבר לחלק בין יחיד לציבור ואנו אומרים אחד יחיד ואחד צבור על כל צרה שעברה משלימים תעניתם חוץ מתענית של גשמים שאין צרה עוברת גמורה אלא צרת גשמים שהיא לשעתה, עכ\"ל:",1,0],[2,9,"שאר מיני רמש וכו'. א\"א אם היו נושכין וממיתין אפי' צרעין ויתושין וזבובים כי כלם שלוחי המקום הם עכ\"ל:",1,0],[2,10,"אבל על החגב וכו'. א\"א אלא חגב ידוע להם שאינו מזיק אבל שאר מינין מזיקים הן שהרי הילק והגזם השחיתו בימי יואל וה\"ה לסלעם וחרגול ועכשיו שאין אנו מכירין מיניהם על כלן מתריעין, עכ\"ל:",1,0],[3,10,"בד\"א בא\"י וכו'. א\"א על ההקדמה איני מודה לו שאע\"פ שיש מקומות שמקדימים וזורעים אין להם הפסד באיחור הגשמים עד הזמן הנזכר במשנה, עכ\"ל:",1,0],[4,17,"ונמצאו הכהנים וכו'. א\"א מן התוספתא אסף את אלה ולא כמ\"ש הוא והתוספתא עצמה משובשת שלא היתה תקיעה עם התרועה ולא התרועה עם התקיעה במקדש ואפשר שהיו שלשתן בגבולין תקיעה תרועה תקיעה, עכ\"ל:",1,0],[5,17,"כל הקרעים וכו'. א\"א לא כן נראה מן הגמרא שהרי שנו בתוספתא לא השוו לאביו ולאמו אלא לאיחוי בלבד אבל בכלי וכל הבגדים שעליו עד שיגלה את לבו לא השוו אבל שיקרע בחוץ לעיני העם גם לזה השוה הנשיא בלבד, עכ\"ל:",1,0]]);
